+const vertexShader = /* glsl */`
+varying vec3 vWorld;
+void main(){
+  vec4 wp = modelMatrix * vec4(position, 1.0);
+  vWorld = wp.xyz;
+  gl_Position = projectionMatrix * viewMatrix * wp;
+}`;
+
+const fragmentShader = /* glsl */`
+#define MAXB 12
+uniform vec3 uBulb; uniform float uBulbR; uniform float uBulbI; uniform vec3 uBulbCol;
+uniform int uCount; uniform vec4 uBlob[MAXB]; uniform vec4 uBlobS[MAXB]; uniform vec4 uPool;
+uniform vec3 uWaxA; uniform vec3 uWaxB; uniform vec3 uLiqA; uniform vec3 uLiqB; uniform float uTime;
+varying vec3 vWorld;
+
+const float YB = 0.085;
+const float YT = 0.40;
+const float YTOP = 0.43;
+const float YLO = 0.089;
+const float YHI = 0.427;
+
+float rOut(float y){
+  float t = clamp((y - YB) / (YT - YB), 0.0, 1.0);
+  float r = mix(0.066, 0.036, t);
+  float u = clamp((y - YT) / (YTOP - YT), 0.0, 1.0);
+  float dome = 0.036 * sqrt(max(1.0 - u*u, 0.0));
+  return y > YT ? dome : r;
+}
+
+// positive inside the vessel interior
+float wallD(vec3 p){
+  float rin = rOut(p.y) - 0.003;
+  return min(rin - length(p.xz), min(p.y - YLO, YHI - p.y));
+}
+
+float sdEll(vec3 p, vec3 r){
+  float k0 = length(p / r);
+  float k1 = length(p / (r * r));
+  return k0 * (k0 - 1.0) / max(k1, 1e-6);
+}
+
+float smin(float a, float b, float k){
+  float h = max(k - abs(a - b), 0.0) / k;
+  return min(a, b) - h*h*k*0.25;
+}
+
+// wax field: x = signed distance, y = temperature of closest lobe
+vec2 waxMap(vec3 p){
+  float vr = uPool.x * 0.5 + 0.01;
+  vec3 pc = vec3(0.0, YB + uPool.x - vr, 0.0);
+  float d = sdEll(p - pc, vec3(uPool.y, vr, uPool.y));
+  float temp = 1.0;
+  for (int i = 0; i < MAXB; i++){
+    if (i >= uCount) break;
+    vec4 b = uBlob[i];
+    vec4 s = uBlobS[i];
+    float di = sdEll(p - b.xyz, b.w * s.xyz);
+    if (di < d) temp = s.w;
+    d = smin(d, di, 0.035);
+  }
+  return vec2(d, temp);
+}
+
+float Ffun(vec3 p){ return max(waxMap(p).x, -wallD(p)); }
+
+void main(){
+  vec3 ro = cameraPosition;
+  vec3 rd = normalize(vWorld - ro);
+  float t = length(vWorld - ro);
+  float tEnter = -1.0;
+  float tHit = -1.0;
+  float tTemp = 1.0;
+  bool entered = false;
+
+  for (int i = 0; i < 110; i++){
+    vec3 p = ro + rd * t;
+    if (i > 0 && (p.y < 0.0625 || p.y > 0.4525 || abs(p.x) > 0.075 || abs(p.z) > 0.075)) break;
