+  if (!entered) discard;
+
+  // analytic bulb
+  vec3 oc = ro - uBulb;
+  float bb = dot(oc, rd);
+  float disc = bb*bb - (dot(oc, oc) - uBulbR*uBulbR);
+  float tb = -1.0;
+  if (disc > 0.0){ float s = -bb - sqrt(disc); if (s > 0.0) tb = s; }
+
+  vec3 col;
+  float depthT;
+
+  if (tb > 0.0 && (tHit < 0.0 || tb < tHit)){
+    vec3 bp = ro + rd * tb;
+    float fr = 1.0 - abs(dot(normalize(bp - uBulb), rd));
+    col = uBulbCol * (0.3 + 5.0 * uBulbI) * (0.8 + 0.4 * fr * fr);
+    depthT = tb;
+  } else if (tHit > 0.0){
+    vec3 hp = ro + rd * tHit;
+    vec2 k = vec2(1.0, -1.0);
+    float h = 0.0015;
+    vec3 n = normalize(k.xyy * Ffun(hp + k.xyy * h) + k.yyx * Ffun(hp + k.yyx * h)
+                     + k.yxy * Ffun(hp + k.yxy * h) + k.xxx * Ffun(hp + k.xxx * h));
+    vec3 V = -rd;
+    vec3 Lv = uBulb - hp;
+    float d2 = dot(Lv, Lv);
+    vec3 Ld = Lv * inversesqrt(d2);
+    float att = uBulbI * 0.02 / (d2 + 0.01);
+    float wrap = clamp((dot(n, Ld) + 0.5) / 1.5, 0.0, 1.0);
+    float spec = pow(max(dot(n, normalize(Ld + V)), 0.0), 48.0);
+    float fres = pow(1.0 - max(dot(n, V), 0.0), 3.0);
+    float thick = 0.0;
+    vec3 q = hp;
+    for (int j = 0; j < 5; j++){ q += rd * 0.009; thick += step(waxMap(q).x, 0.0) * 0.009; }
