+    float trans = exp(-thick * 6.0);
+    vec3 lc = uBulbCol * att;
+    col = base * (0.04 + lc * wrap * 0.85);
+    col += base * lc * trans * 1.5;               // subsurface glow through thin wax
+    col += uBulbCol * spec * att * 0.5;
+    col += base * fres * 0.12;
+    depthT = tHit;
+  } else {
+    vec3 hp = ro + rd * tEnter;
