+const bulbLight = new THREE.PointLight(0xff9a48, 0.0045, 2.5, 2);
+bulbLight.position.copy(BULB);
+scene.add(bulbLight);
+
+const key = new THREE.SpotLight(0xffe6c8, 2.4, 0, 0.55, 0.9, 2);
+key.position.set(0.7, 1.25, 0.8);
+key.target.position.set(0, 0.1, 0);
+key.castShadow = true;
+key.shadow.mapSize.set(2048, 2048);
+key.shadow.bias = -0.0004;
+key.shadow.camera.near = 0.3;
+key.shadow.camera.far = 4;
+scene.add(key, key.target);
+
+const hemi = new THREE.HemisphereLight(0x4a4038, 0x0a0806, 0.25);
+scene.add(hemi);
+
+// ---------- post ----------
+const rt = new THREE.WebGLRenderTarget(innerWidth, innerHeight, { type: THREE.HalfFloatType, samples: 4 });
+const composer = new EffectComposer(renderer, rt);
+composer.addPass(new RenderPass(scene, camera));
+const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 0.5, 0.45, 0.8);
+composer.addPass(bloom);
+const FilmShader = {
+  uniforms: { tDiffuse: { value: null }, uTime: { value: 0 }, uVig: { value: 0.55 } },
+  vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
+  fragmentShader: `
+    uniform sampler2D tDiffuse; uniform float uTime; uniform float uVig; varying vec2 vUv;
+    float h(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
+    void main(){
+      vec4 c = texture2D(tDiffuse, vUv);
+      vec2 d = vUv - 0.5;
+      c.rgb *= clamp(1.0 - dot(d, d) * uVig * 2.0, 0.0, 1.0);
+      c.rgb += (h(vUv * 1000.0 + uTime) - 0.5) * 0.02;
+      gl_FragColor = c;
+    }`,
+};
+const film = new ShaderPass(FilmShader);
+composer.addPass(film);
+composer.addPass(new OutputPass());
+
+// ---------- simulation ----------
+const S = {
+  blobs: [], poolH: 0.05, P: 1, Ptarget: 1, spawnIn: 1.5, swell: null,
+  time: 0, occl: 0, bulbI: 1,
+};
+
+function newBlob(x, y, z, r, T, vy = 0) {
+  const b = { p: new THREE.Vector3(x, y, z), v: new THREE.Vector3(0, vy, 0), r, T, sy: 1,
+    ph: Math.random() * 6.283, swell: false, sink: false, rT: r };
+  S.blobs.push(b);
+  return b;
+}
+
+function constrain(b) {
+  const sxz = 1 / Math.sqrt(b.sy);
+  const ry = b.r * b.sy, rx = b.r * sxz;
+  const rin = rOutJ(b.p.y) - 0.003 - rx - 0.001;
+  const rad = Math.hypot(b.p.x, b.p.z);
+  if (rad > rin) {
+    const k = Math.max(rin, 0) / Math.max(rad, 1e-6);
+    b.p.x *= k; b.p.z *= k;
+    b.v.x *= 0.3; b.v.z *= 0.3;
+  }
+  const lo = 0.089 + ry;
+  if (b.p.y < lo) { b.p.y = lo; if (b.v.y < 0) b.v.y *= -0.3; }
+  const hi = 0.427 - ry;
+  if (b.p.y > hi) { b.p.y = hi; if (b.v.y > 0) b.v.y *= -0.3; }
+}
+
+// seed a lively initial state
+newBlob(0.01, 0.2, -0.01, 0.026, 0.95, 0.02);
+newBlob(-0.012, 0.29, 0.01, 0.022, 0.7, 0.01);
+newBlob(0.01, 0.12, 0.02, 0.02, 0.9, 0.0);
+newBlob(0.02, 0.36, 0.0, 0.024, 0.15, -0.02);
+
+const camDir = new THREE.Vector3();
+const toB = new THREE.Vector3();
+
+function simStep(dt) {
+  S.time += dt;
+  const t = S.time, flow = params.flow, amt = params.amount;
+
+  // power ramp: warm up slowly, cool down slowly
+  S.P += (S.Ptarget - S.P) * (1 - Math.exp(-dt / (S.Ptarget > 0.5 ? 2.2 : 3.5)));
+  // pool drifts toward the wax amount target
+  S.poolH += (0.035 + 0.06 * amt - S.poolH) * dt * 0.05;
+
+  // heat + buoyancy + drift
+  for (const b of S.blobs) {
+    if (b.swell) continue;
+    const ttgt = S.P * hotT(b.p.y) + (1 - S.P) * 0.12;
+    b.T += (ttgt - b.T) * (1 - Math.exp(-dt * 0.8 * flow));
+    if (b.sink) b.v.y = Math.min(b.v.y, -0.02);
+    else b.v.y += ((b.T - 0.5) * 0.2 * flow - 3.3 * b.v.y) * dt;
+    b.v.x += (Math.sin(t * 0.6 + b.ph) * 0.01 - 1.2 * b.v.x - 0.02 * b.p.x) * dt;
+    b.v.z += (Math.cos(t * 0.5 + b.ph * 1.3) * 0.01 - 1.2 * b.v.z - 0.02 * b.p.z) * dt;
+    const stretchT = 1 + clamp(b.v.y * 15, -0.3, 0.8);
+    b.sy += (stretchT - b.sy) * (1 - Math.exp(-dt * 3));
+    b.p.addScaledVector(b.v, dt);
+    constrain(b);
+  }
+
+  // cold blobs reaching the pool sink into it
+  for (const b of S.blobs) {
+    if (b.swell) continue;
+    if (!b.sink && b.T < 0.45 && b.v.y < 0.005 && b.p.y - b.r * b.sy < YB + S.poolH + 0.012) b.sink = true;
+    if (b.sink) {
+      const v0 = volOf(b.r);
+      b.r = Math.max(b.r - dt * 0.03, 0);
+      S.poolH += (v0 - volOf(b.r)) / POOL_A;
+    }
+  }
+  S.blobs = S.blobs.filter(b => !(b.sink && b.r < 0.003));
+
+  // merge overlapping blobs (one per step)
+  outer: for (let i = 0; i < S.blobs.length; i++) {
+    for (let j = i + 1; j < S.blobs.length; j++) {
+      const a = S.blobs[i], c = S.blobs[j];
+      if (a.swell || c.swell || a.sink || c.sink) continue;
+      if (a.p.distanceTo(c.p) < 0.6 * (a.r + c.r)) {
+        const va = volOf(a.r), vc = volOf(c.r), vt = va + vc, rn = radOf(vt);
+        if (rn > 0.05) continue;
+        a.p.multiplyScalar(va / vt).addScaledVector(c.p, vc / vt);
+        a.v.multiplyScalar(va / vt).addScaledVector(c.v, vc / vt);
+        a.T = (a.T * va + c.T * vc) / vt;
+        a.r = rn;
+        S.blobs.splice(j, 1);
+        break outer;
+      }
+    }
+  }
+
+  // split (big blobs) and pinch off droplets (stretched blobs)
+  for (const b of S.blobs) {
+    if (S.blobs.length >= MAXB) break;
+    if (b.swell || b.sink) continue;
+    if (b.r > 0.034 && b.T > 0.4 && Math.random() < 0.3 * dt) {
+      const ang = Math.random() * 6.283, vTot = volOf(b.r), vc = vTot * 0.3, off = b.r * 0.55;
+      b.r = radOf(vTot - vc);
+      b.p.x -= Math.cos(ang) * off * 0.5; b.p.z -= Math.sin(ang) * off * 0.5;
+      const c = newBlob(b.p.x + Math.cos(ang) * off, b.p.y, b.p.z + Math.sin(ang) * off, radOf(vc), b.T);
+      c.v.set(Math.cos(ang) * 0.012, b.v.y, Math.sin(ang) * 0.012);
+      break;
+    }
+    if (b.sy > 1.55 && b.r > 0.017 && b.T > 0.5 && Math.random() < 0.5 * dt) {
+      const vTot = volOf(b.r), vc = vTot * 0.07;
+      b.r = radOf(vTot - vc);
+      newBlob(b.p.x, b.p.y + b.r * b.sy * 0.75, b.p.z, radOf(vc), b.T, b.v.y * 1.4 + 0.01);
+      break;
+    }
+  }
+
+  // swelling blob attached to the pool, then detaches
+  if (S.swell) {
+    const b = S.swell;
+    const vT = volOf(b.rT), vNow = volOf(b.r);
+    const vNew = Math.min(vNow + vT / 3.5 * dt, vT);
+    b.r = radOf(vNew);
+    S.poolH = Math.max(S.poolH - (vNew - vNow) / POOL_A, 0.004);
+    b.p.set(b.p.x, YB + S.poolH + b.r * 0.3, b.p.z);
+    b.v.set(0, 0, 0);
+    b.T = 1;
+    if (b.r >= b.rT * 0.97) {
+      b.swell = false; b.v.y = 0.012; b.sy = 1; S.swell = null;
+      S.spawnIn = rnd(1.5, 3) / flow;
+    }
+  } else {
+    S.spawnIn -= dt;
+    if (S.P > 0.85 && S.poolH > 0.02 && S.blobs.length < MAXB && S.spawnIn <= 0) {
+      const b = newBlob(rnd(-0.015, 0.015), YB + S.poolH, rnd(-0.015, 0.015), 0.008, 1);
+      b.swell = true;
+      b.rT = rnd(0.022, 0.03) * Math.cbrt(amt);
+      S.swell = b;
+    }
+  }
+
+  // bulb occlusion: wax between bulb and camera dims the glow
+  camDir.copy(camera.position).sub(BULB).normalize();
+  let occ = 0;
+  for (const b of S.blobs) {
+    toB.copy(b.p).sub(BULB);
+    const along = toB.dot(camDir);
+    if (along > 0) {
+      const perp = toB.clone().addScaledVector(camDir, -along).length();
+      if (perp < b.r + BULB_R) occ += clamp(1 - perp / (b.r + BULB_R), 0, 1) * 0.5;
+    }
+  }
+  S.occl += (clamp(occ, 0, 0.8) - S.occl) * (1 - Math.exp(-dt * 20));
+  S.bulbI = S.P * (0.93 + 0.04 * Math.sin(t * 5.3) + 0.03 * Math.sin(t * 11.7 + 1.2) + 0.02 * Math.sin(t * 23.1))
+    * (1 - 0.6 * S.occl);
+}
+
+function syncUniforms() {
+  const n = Math.min(S.blobs.length, MAXB);
+  U.uCount.value = n;
+  for (let i = 0; i < n; i++) {
+    const b = S.blobs[i];
+    const sxz = 1 / Math.sqrt(b.sy);
+    U.uBlob.value[i].set(b.p.x, b.p.y, b.p.z, b.r);
+    U.uBlobS.value[i].set(sxz, b.sy, sxz, b.T);
+  }
+  U.uPool.value.set(S.poolH, RP, 0, 0);
+  U.uBulbI.value = S.bulbI;
+  U.uTime.value = S.time;
+
+  bulbLight.intensity = 0.0045 * S.bulbI + 0.0002;
+  glowDecal.material.opacity = 0.65 * S.bulbI;
+  key.intensity = 2.4 * params.room;
+  hemi.intensity = 0.1 + 0.2 * params.room;
+}
+
+// ---------- presets ----------
+const setV = (v, hex) => { const c = new THREE.Color(hex); v.set(c.r, c.g, c.b); };
+const presetsEl = document.getElementById('presets');
+let activePreset = 0;
+function applyPreset(i) {
+  activePreset = i;
+  const p = PRESETS[i];
+  setV(U.uWaxA.value, p.wax[0]); setV(U.uWaxB.value, p.wax[1]);
+  setV(U.uLiqA.value, p.liq[0]); setV(U.uLiqB.value, p.liq[1]);
+  glassMat.attenuationColor.setHex(p.liq[1]);
+  [...presetsEl.children].forEach((el, k) => el.classList.toggle('active', k === i));
+}
+PRESETS.forEach((p, i) => {
+  const btn = document.createElement('button');
+  btn.className = 'preset';
+  btn.title = p.name;
+  btn.style.background = `linear-gradient(120deg, #${p.wax[0].toString(16).padStart(6, '0')} 0 50%, #${p.liq[0].toString(16).padStart(6, '0')} 50% 100%)`;
+  btn.addEventListener('click', () => applyPreset(i));
+  presetsEl.appendChild(btn);
+});
+applyPreset(0);
+
+// ---------- power ----------
+const powerBtn = document.getElementById('power');
+function setPower(on) {
+  S.Ptarget = on ? 1 : 0;
+  powerBtn.classList.toggle('on', on);
+}
+powerBtn.addEventListener('click', () => setPower(S.Ptarget < 0.5));
+powerBtn.classList.add('on');
+
+const raycaster = new THREE.Raycaster();
+renderer.domElement.addEventListener('pointerdown', e => {
+  const r = renderer.domElement.getBoundingClientRect();
+  const ndc = new THREE.Vector2(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
+  raycaster.setFromCamera(ndc, camera);
+  if (raycaster.intersectObject(housing).length) setPower(S.Ptarget < 0.5);
+});
+
+// ---------- UI ----------
+document.getElementById('flow').addEventListener('input', e => params.flow = +e.target.value);
+document.getElementById('amount').addEventListener('input', e => params.amount = +e.target.value);
+document.getElementById('room').addEventListener('input', e => params.room = +e.target.value);
+document.getElementById('orbit').addEventListener('change', e => controls.autoRotate = e.target.checked);
+
+// ---------- resize + adaptive resolution ----------
+let quality = 1;
+function setQuality(q) {
+  const pr = Math.min(devicePixelRatio, 1.5) * q;
+  renderer.setPixelRatio(pr);
+  composer.setPixelRatio(pr);
+}
+function onResize() {
+  camera.aspect = innerWidth / innerHeight;
+  camera.updateProjectionMatrix();
+  renderer.setSize(innerWidth, innerHeight);
+  composer.setSize(innerWidth, innerHeight);
+}
+window.addEventListener('resize', onResize);
+setQuality(quality);
+onResize();
+
+let fAvg = 16.7, lastQ = 0;
+function adapt(now, dtMs) {
+  fAvg = fAvg * 0.9 + dtMs * 0.1;
+  if (now - lastQ > 1200) {
+    lastQ = now;
+    let q = quality;
+    if (fAvg > 21 && q > 0.5) q -= 0.1;
+    else if (fAvg < 15 && q < 1) q += 0.05;
+    q = Math.round(q * 100) / 100;
+    if (q !== quality) { quality = q; setQuality(q); onResize(); }
+  }
+}
+
+// ---------- loop ----------
+let acc = 0, prev = performance.now();
+function frame(now) {
+  const dtMs = Math.min(now - prev, 100);
+  prev = now;
+  acc += dtMs / 1000;
+  let steps = 0;
+  while (acc >= FIXED && steps < 12) { simStep(FIXED); acc -= FIXED; steps++; }
+  if (steps >= 12) acc = 0;
+
+  // lever follows power state
+  const leverTarget = S.Ptarget > 0.5 ? -0.4 : 0.4;
+  lever.rotation.x += (leverTarget - lever.rotation.x) * 0.15;
+
+  controls.update();
+  syncUniforms();
+  film.uniforms.uTime.value = now * 0.001;
+  composer.render();
+  adapt(now, dtMs);
+  requestAnimationFrame(frame);
+}
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>
